"""Public, non-secret release metadata generated by the allowlisted package builder."""

import json
from pathlib import Path
from .config import settings


def information() -> dict:
    path = Path(__file__).resolve().parents[1] / "release.json"
    if path.is_file():
        data = json.loads(path.read_text())
        return {
            key: data.get(key)
            for key in (
                "git_commit",
                "build_version",
                "built_utc",
                "frontend_sha256",
                "backend_sha256",
                "required_migration",
                "supported_migrations",
                "sso_required_migration",
            )
        }
    return {
        "build_version": settings.build_version,
        "required_migration": "010",
        "supported_migrations": ["004", "005", "006", "007", "008", "009", "010"],
        "sso_required_migration": "005",
        "git_commit": "unpackaged-working-tree",
    }
